/** One page by its path, with its sections. */
export const pageQuery = `*[_type == "page" && slug.current == $slug][0]{ title, description, "slug": slug.current, "sections": sections${sectionsProjection} }`;

/** The site-wide sections. */
export const siteSettingsQuery = `*[_type == "siteSettings"][0]{ "announcement": announcement${announcementSectionProjection}, "header": header${headerSectionProjection}, "footer": footer${footerSectionProjection} }`;

/** Post documents, newest first (date desc), one page of them: params $start and $end (0 and 12 for the first twelve). */
export const postListQuery = `*[_type == "post"] | order(date desc) [$start...$end]${postProjection}`;

/** How many post documents there are (for pagination). */
